"""Static reader entrypoints; scientific data is loaded from separate reviewed records."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def shell(title,body,script):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · MatterSyn</title><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 40 40%27%3E%3Crect width=%2740%27 height=%2740%27 rx=%279%27 fill=%27%23295888%27/%3E%3Ctext x=%2720%27 y=%2728%27 text-anchor=%27middle%27 fill=%27white%27 font-size=%2726%27%3EM%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="academic.css"><link rel="stylesheet" href="dataset.css"><link rel="stylesheet" href="atlas.css?v=0.7.0-r2"><link rel="stylesheet" href="apparatus.css"><link rel="stylesheet" href="illustrated-guide.css?v=0.7.0-r2"></head><body><header class="site-header atlas-header"><a class="brand" href="index.html"><span class="brand-mark">M</span>MatterSyn</a><nav aria-label="Atlas navigation"><a href="index.html">Periodic table</a><a href="library.html">Source library</a><a href="dataset.html">Synthesis dataset</a></nav></header><main class="dataset-main">'+body+'</main><script src="vendor/3Dmol-min.js"></script><script type="module" src="'+script+'?v=0.7.0-r2"></script></body></html>'
def main():
    library='''<div class="dataset-heading"><span class="eyebrow">FULL-FOLDER SOURCE INDEX</span><h1>Source library</h1><p><a href="inventory.html">Materials and synthesis inventory →</a></p><p>Find papers and supporting information. Review status stays separate from automatic document extraction.</p></div><div class="library-summary"><div><strong id="document-total">—</strong><span>Documents inventoried</span></div><div><strong id="paper-total">—</strong><span>Local paper groups</span></div><div><strong id="extracted-total">—</strong><span>Documents with extracted text</span></div><div><strong id="reviewed-total">—</strong><span>Papers with reviewed recipe records</span></div></div><p id="corpus-state" class="coverage-note"></p><p id="full-review-state" class="coverage-note"></p><div class="atlas-results-head"><h2>Papers<small id="paper-count" aria-live="polite"></small></h2><div class="atlas-filters"><input id="paper-search" class="atlas-search" type="search" aria-label="Search papers by title, DOI or material" placeholder="Title, DOI or material"><select id="paper-status" aria-label="Paper review status"><option value="">All papers</option><option value="full_documents_reviewed">Full main + matched SI reviewed</option><option value="main_only_reviewed">Full main reviewed · SI unverified</option><option value="selected_recipes_reviewed">Selected recipes reviewed</option><option value="indexed_awaiting_review">Awaiting detailed review</option><option value="published_benchmark">Published benchmark</option></select></div></div><div id="paper-results" class="library-list"></div><div class="library-pagination"><button class="atlas-button" id="paper-prev">← Previous</button><span id="paper-page"></span><button class="atlas-button" id="paper-next">Next →</button></div><p class="atlas-footnote">Titles, paper/SI grouping and formula mentions are automatically extracted candidates unless a reviewed record verifies them. No indexed paper becomes a training example merely by appearing here.</p>'''
    material='''<nav class="material-hub-nav" aria-label="Atlas hierarchy"><a href="index.html">Periodic table</a><span>→</span><span>Material</span><span>→</span><a id="material-dataset" href="dataset.html">Material synthesis dataset</a></nav><div class="material-intro"><span id="material-elements" class="eyebrow"></span><h1 id="material-formula">Material</h1><p id="material-name"></p></div><p id="material-scope-note" class="coverage-note"></p><nav class="material-hub-nav"><a href="#methods">Synthesis methods</a><a href="#structures">Final structures</a><a href="#properties">Properties</a><a href="#intuition">Chemical intuition</a><a href="#literature">Literature</a></nav><div id="material-illustrated-guide"></div><section id="methods" class="record-section"><h2>Synthesis methods<small>Precursors and protocols remain attached to their source records.</small></h2><div id="material-methods" class="method-grid"></div></section><section id="structures" class="record-section"><h2>Final structures<small>Source-specific phase, morphology and structural characterization</small></h2><div id="material-structures" class="paper-contributions"></div></section><section id="original-evidence" class="record-section"><h2>Original characterization and property figures</h2><div id="material-original-evidence"></div></section><section id="properties" class="record-section"><h2>Properties<small>Measurements retain their sample and recipe linkage.</small></h2><div id="material-properties" class="paper-contributions"></div></section><section id="intuition" class="record-section"><h2>Chemical intuition</h2><div id="material-intuition-content"></div><p>Mechanistic interpretation remains in each reviewed contribution, with its own references and experimental-system boundaries. Unreviewed literature is not used to fill missing conditions or explain an author’s intent.</p></section><section id="literature" class="record-section"><h2>Literature contributions</h2><p id="paper-contribution-count"></p><div id="material-papers" class="paper-contributions"></div><button type="button" id="more-papers" class="atlas-button" hidden>Show more papers</button></section>'''
    paper='''<nav class="material-hub-nav"><a href="index.html">Periodic table</a><span>→</span><a href="library.html">Source library</a><span>→</span><span>Paper record</span></nav><div class="dataset-heading"><span class="eyebrow">SOURCE COVERAGE RECORD</span><h1 id="paper-title">Paper</h1><p><a id="paper-doi"></a></p><p id="paper-title-status"></p></div><p id="paper-review" class="coverage-note"></p><div id="paper-full-review" class="review-actions"></div><section class="record-section"><h2>Main article and supporting information</h2><p id="paper-coverage"></p><p id="paper-extraction"></p></section><section class="record-section"><h2>Material collections</h2><div id="paper-materials"></div><p class="atlas-footnote">Only source-reviewed synthesis contributions link to material pages. Unreviewed title mentions remain search candidates in the library.</p></section><section class="record-section"><h2>Reviewed records and benchmark rows</h2><div id="paper-records"></div></section><p id="paper-source-note" class="coverage-note"></p>'''
    review='<nav class="material-hub-nav"><a href="index.html">Periodic table</a><span>→</span><a href="library.html">Source library</a><span>→</span><span>Full-document review</span></nav><div class="dataset-heading"><span class="eyebrow">SOURCE DOCUMENT REVIEW</span><h1 id="review-title">Source review</h1><p><a id="review-doi"></a></p></div><p class="coverage-note" id="review-summary">Loading reviewed source coverage…</p><div class="review-actions"><a id="review-download">Download machine-readable coverage JSON ↓</a><a href="library.html">Source library →</a></div><nav class="review-subnav"><a href="#documents">Pages reviewed</a><a href="#recipes">Recipes and controls</a><a href="#characterization">Characterization</a><a href="#figures">Original figures</a><a href="#gaps">Unresolved details</a></nav><div id="review-body"><section id="documents" class="record-section"></section><section id="recipes" class="record-section"></section><section id="characterization" class="record-section"></section><section id="figures" class="record-section"></section><section id="gaps" class="record-section"></section></div><dialog class="review-dialog" id="figure-dialog"><header><h2 id="figure-title">Original figure</h2><button id="figure-close" type="button">Close ×</button></header><img id="figure-large" alt="Original figure"></dialog>'
    (ROOT/'dist/paper-review.html').write_text(shell('Full-document review',review,'paper-review.mjs').replace('</head>','<link rel="stylesheet" href="paper-review.css"></head>'),encoding='utf-8')
    for name,title,body,script in [('library.html','Source library',library,'library-app.mjs'),('material.html','Material collection',material,'material-hub.mjs'),('paper.html','Paper coverage',paper,'paper-app.mjs')]:
        (ROOT/'dist'/name).write_text(shell(title,body,script),encoding='utf-8')
if __name__=='__main__':main()
